import java.util.Iterator;
import sailpoint.object.AuditEvent;
import sailpoint.object.Certification;
import sailpoint.object.CertificationAction;
import sailpoint.object.CertificationEntity;
import sailpoint.object.CertificationItem;
import sailpoint.server.Auditor;

if (nextPhase != Certification.Phase.Remediation && nextPhase != Certification.Phase.End) {
    return;
}
int count = 0;
for (Iterator e = certification.getEntities().iterator(); e.hasNext();) {
    CertificationEntity entity = (CertificationEntity) e.next();
    if (entity.getItems() == null) {
        continue;
    }
    for (Iterator i = entity.getItems().iterator(); i.hasNext();) {
        CertificationItem item = (CertificationItem) i.next();
        CertificationAction action = item.getAction();
        if (action == null || action.getStatus() != CertificationAction.Status.Remediated) {
            continue;
        }
        AuditEvent ev = new AuditEvent();
        ev.setAction("fsgovRevocationDecision");
        ev.setSource(action.getActorName());
        ev.setTarget(entity.getIdentity());
        ev.setString1(certification.getName());
        ev.setString2(item.getShortDescription());
        ev.setString3(nextPhase.toString());
        ev.setAttribute("decisionDate", action.getDecisionDate());
        ev.setAttribute("remediationKickedOff", Boolean.valueOf(action.isRemediationKickedOff()));
        ev.setAttribute("comments", action.getComments());
        Auditor.log(ev);
        count++;
    }
}
context.commitTransaction();
log.info("fsgov: recorded " + count + " revocation decisions for " + certification.getName());
